// Embedded turtle source — martech-ontology.ttl + *-instances.ttl, for the in-browser SPARQL engine (no fetch, works via file://).
const ONTOLOGY_TTL = "# ==========================================================================\n# Unified martech knowledge graph — ontology (v1, schema only, no instance data)\n# Namespace: martech  (placeholder base URI — swap for your real one)\n# Style: RDFS-level only (no OWL reasoning/constraints, intentionally)\n# ==========================================================================\n\n@prefix martech: <https://example.org/martech/ontology/> .\n@prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n\n# --------------------------------------------------------------------------\n# Core classes\n# --------------------------------------------------------------------------\n\nmartech:Requirement a rdfs:Class ;\n    rdfs:comment \"The business problem, question, or hypothesis that justifies tracking something.\" .\n\nmartech:KPI a rdfs:Class ;\n    rdfs:comment \"A measurable objective that addresses a requirement.\" .\n\nmartech:Journey a rdfs:Class ;\n    rdfs:comment \"A named, end-to-end customer path.\" .\n\nmartech:Stage a rdfs:Class ;\n    rdfs:comment \"An ordered step within a journey.\" .\n\nmartech:Feature a rdfs:Class ;\n    rdfs:comment \"A reusable functional capability of the product. Not sequential; can be used by multiple stages or journeys.\" .\n\nmartech:Component a rdfs:Class ;\n    rdfs:comment \"A metric or dimension from the semantic layer (CJA Semantic Layer MCP). Identity is authoritative in AEP; business meaning (definition, caveats, context) is curated here.\" .\n\nmartech:DataLayerVariable a rdfs:Class ;\n    rdfs:comment \"The raw implementation artifact (e.g. a data layer field) that populates a component.\" .\n\n# --------------------------------------------------------------------------\n# N-ary relation classes\n#\n# Used where a relationship itself needs an attribute (e.g. a conversion\n# rate, or a filter value). A plain RDF predicate can only connect two\n# resources with no attribute of its own, so these relationships are\n# modeled as their own nodes instead of plain triples.\n# Pattern reference: https://www.w3.org/TR/swbp-n-aryRelations/\n# --------------------------------------------------------------------------\n\nmartech:StageTransition a rdfs:Class ;\n    rdfs:comment \"An empirical transition between two stages (CJA-sourced), carrying a conversion rate. Stands in for a plain 'next' predicate because the relationship itself has an attribute.\" .\n\nmartech:Measurement a rdfs:Class ;\n    rdfs:comment \"A 'measured_by' relationship between a Stage or Feature and a Component, optionally qualified by a filter value (e.g. a specific page-name value that identifies the stage).\" .\n\n# --------------------------------------------------------------------------\n# Direct predicates (no attributes of their own)\n# --------------------------------------------------------------------------\n\nmartech:addressed_by a rdf:Property ;\n    rdfs:domain martech:Requirement ;\n    rdfs:range martech:KPI ;\n    rdfs:comment \"Links a requirement to the KPI that measures it.\" .\n\nmartech:has_stage a rdf:Property ;\n    rdfs:domain martech:Journey ;\n    rdfs:range martech:Stage ;\n    rdfs:comment \"Links a journey to one of its ordered stages.\" .\n\nmartech:uses_feature a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range martech:Feature ;\n    rdfs:comment \"Links a stage to a feature it involves.\" .\n\nmartech:rolls_up_to a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range martech:KPI ;\n    rdfs:comment \"Links a stage's outcome to the KPI it contributes to.\" .\n\nmartech:contributes_to a rdf:Property ;\n    rdfs:domain martech:KPI ;\n    rdfs:range martech:KPI ;\n    rdfs:comment \"Links a KPI to a higher-level KPI it rolls up into (KPI hierarchy).\" .\n\nmartech:maps_to a rdf:Property ;\n    rdfs:domain martech:DataLayerVariable ;\n    rdfs:range martech:Component ;\n    rdfs:comment \"Links a raw implementation variable to the semantic component it populates.\" .\n\nmartech:refs a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range rdfs:Resource ;\n    rdfs:comment \"Points to the authoritative entity in AEP's own native knowledge graph (e.g. an XDM path URI). Reference only — never duplicated locally.\" .\n\n# --------------------------------------------------------------------------\n# N-ary relation predicates\n# --------------------------------------------------------------------------\n\nmartech:transition_from a rdf:Property ;\n    rdfs:domain martech:StageTransition ;\n    rdfs:range martech:Stage ;\n    rdfs:comment \"The stage a transition starts from.\" .\n\nmartech:transition_to a rdf:Property ;\n    rdfs:domain martech:StageTransition ;\n    rdfs:range martech:Stage ;\n    rdfs:comment \"The stage a transition leads to.\" .\n\nmartech:conversion_rate a rdf:Property ;\n    rdfs:domain martech:StageTransition ;\n    rdfs:range xsd:decimal ;\n    rdfs:comment \"Share of people from the origin stage who reached the destination stage.\" .\n\nmartech:measured_entity a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range rdfs:Resource ;\n    rdfs:comment \"The Stage or Feature being measured.\" .\n\nmartech:measured_component a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range martech:Component ;\n    rdfs:comment \"The component used to measure the entity.\" .\n\nmartech:filter_value a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Optional. The specific dimension value that identifies this measurement (e.g. a page-name value for a shared page-name component).\" .\n\n# --------------------------------------------------------------------------\n# Datatype properties (business-meaning / descriptive attributes)\n# --------------------------------------------------------------------------\n\nmartech:status a rdf:Property ;\n    rdfs:domain martech:Requirement ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Lifecycle status of a requirement, e.g. active, answered, retired.\" .\n\nmartech:formula a rdf:Property ;\n    rdfs:domain martech:KPI ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"The formula or definition of a KPI.\" .\n\nmartech:target a rdf:Property ;\n    rdfs:domain martech:KPI ;\n    rdfs:range xsd:decimal ;\n    rdfs:comment \"The target or benchmark value for a KPI.\" .\n\nmartech:order a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range xsd:integer ;\n    rdfs:comment \"Position of the stage within its journey.\" .\n\nmartech:entry_criteria a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"What defines that a user has entered this stage.\" .\n\nmartech:definition a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Plain-language business meaning of the component. Curated here — not present in AEP's own graph.\" .\n\nmartech:caveats a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Known data-quality issues, gaps, or limitations of the component.\" .\n\nmartech:context a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Business or industry context explaining why the component matters.\" .\n\nmartech:component_type a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Whether the component is a metric or a dimension.\" .\n\nmartech:source_system a rdf:Property ;\n    rdfs:domain martech:DataLayerVariable ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Where the raw variable is implemented, e.g. the tagging/data layer system.\" .\n\nmartech:owner a rdf:Property ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Person or team responsible. Reused across Requirement, KPI, Journey, Component, and Feature — intentionally left without a fixed domain.\" .\n";
const ECOMMERCE_TTL = "# ==========================================================================\n# Ecommerce purchase funnel — instance data\n# Conforms to: martech-ontology.ttl (load both into the same graph)\n# Namespace for instances kept separate from the ontology namespace,\n# so multiple journeys' data can live in their own files later.\n# ==========================================================================\n\n@prefix martech: <https://example.org/martech/ontology/> .\n@prefix data:    <https://example.org/martech/data/ecommerce/> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n\n# --------------------------------------------------------------------------\n# Requirement\n# --------------------------------------------------------------------------\n\ndata:req_shop_performance a martech:Requirement ;\n    rdfs:label \"Understand shop performance and drop-off\" ;\n    rdfs:comment \"We want to understand how our shop is performing, and where in the journey people drop off.\" ;\n    martech:status \"active\" ;\n    martech:addressed_by data:kpi_order_conversion_rate .\n\n# --------------------------------------------------------------------------\n# KPI\n# --------------------------------------------------------------------------\n\ndata:kpi_order_conversion_rate a martech:KPI ;\n    rdfs:label \"Order conversion rate\" ;\n    martech:formula \"Orders / Product Views\" ;\n    martech:owner \"Ecommerce / Digital Marketing\" ;\n    martech:target 0.0020 ;\n    rdfs:comment \"Current value (2026): 0.11%. Target: 0.20% (illustrative example, not a real commitment).\" .\n\n# --------------------------------------------------------------------------\n# Journey\n# --------------------------------------------------------------------------\n\ndata:journey_ecommerce_funnel a martech:Journey ;\n    rdfs:label \"Ecommerce purchase journey\" ;\n    martech:owner \"Digital Marketing\" ;\n    martech:has_stage data:stage_product_view, data:stage_cart_add, data:stage_checkout, data:stage_order .\n\n# --------------------------------------------------------------------------\n# Stages\n# --------------------------------------------------------------------------\n\ndata:stage_product_view a martech:Stage ;\n    rdfs:label \"Product view\" ;\n    martech:order 1 .\n\ndata:stage_cart_add a martech:Stage ;\n    rdfs:label \"Cart add\" ;\n    martech:order 2 .\n\ndata:stage_checkout a martech:Stage ;\n    rdfs:label \"Checkout\" ;\n    martech:order 3 .\n\ndata:stage_order a martech:Stage ;\n    rdfs:label \"Order\" ;\n    martech:order 4 ;\n    martech:rolls_up_to data:kpi_order_conversion_rate .\n\n# --------------------------------------------------------------------------\n# Components\n# NOTE: refs use a placeholder sandbox segment — swap SANDBOX_NAME for the\n# real Champ sandbox name once confirmed.\n# --------------------------------------------------------------------------\n\ndata:component_product_views a martech:Component ;\n    rdfs:label \"Product views\" ;\n    martech:component_type \"metric\" ;\n    martech:definition \"Number of times a product detail page was viewed.\" ;\n    martech:caveats \"Counts page views, not unique visitors — a visitor viewing the same product twice counts twice.\" ;\n    martech:context \"Entry point for the purchase funnel; used to benchmark top-of-funnel demand.\" ;\n    martech:owner \"Digital Analytics\" ;\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.productViews.value> .\n\ndata:component_product_list_adds a martech:Component ;\n    rdfs:label \"Product list adds\" ;\n    martech:component_type \"metric\" ;\n    martech:definition \"Number of times a product was added to the cart.\" ;\n    martech:caveats \"Does not deduplicate repeated adds of the same product within one session.\" ;\n    martech:context \"First explicit purchase-intent signal in the funnel.\" ;\n    martech:owner \"Digital Analytics\" ;\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.productListAdds.value> .\n\ndata:component_checkouts a martech:Component ;\n    rdfs:label \"Checkouts\" ;\n    martech:component_type \"metric\" ;\n    martech:definition \"Number of times a user started the checkout process.\" ;\n    martech:caveats \"Counts checkout starts, not completions — a user can start checkout multiple times without purchasing.\" ;\n    martech:context \"Marks the transition from browsing to transactional intent.\" ;\n    martech:owner \"Digital Analytics\" ;\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.checkouts.value> .\n\ndata:component_orders a martech:Component ;\n    rdfs:label \"Orders\" ;\n    martech:component_type \"metric\" ;\n    martech:definition \"Number of completed purchase orders.\" ;\n    martech:caveats \"Includes orders later cancelled or refunded — not net of returns.\" ;\n    martech:context \"The funnel's terminal event and the numerator of the order conversion rate KPI.\" ;\n    martech:owner \"Digital Analytics\" ;\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/orders> .\n\n# --------------------------------------------------------------------------\n# Data layer variable\n# ASSUMPTION: one shared \"funnel step\" field feeds all 4 stage components\n# (maps_to is many-to-many per the ontology design) — flagging this as a\n# guess, not confirmed from the sandbox implementation.\n# --------------------------------------------------------------------------\n\ndata:dlv_conversion_funnel_step a martech:DataLayerVariable ;\n    rdfs:label \"digitalData.conversion.conversionFunnel.step\" ;\n    martech:source_system \"Web data layer (digitalData)\" ;\n    martech:maps_to data:component_product_views, data:component_product_list_adds,\n                     data:component_checkouts, data:component_orders .\n\n# --------------------------------------------------------------------------\n# Measurements (Stage <-> Component, via the n-ary Measurement class)\n# No filter_value needed here — unlike a shared-dimension pattern\n# (see the login journey), each stage here has its own distinct\n# distinct component rather than sharing one dimension.\n# --------------------------------------------------------------------------\n\ndata:measurement_product_view a martech:Measurement ;\n    martech:measured_entity data:stage_product_view ;\n    martech:measured_component data:component_product_views .\n\ndata:measurement_cart_add a martech:Measurement ;\n    martech:measured_entity data:stage_cart_add ;\n    martech:measured_component data:component_product_list_adds .\n\ndata:measurement_checkout a martech:Measurement ;\n    martech:measured_entity data:stage_checkout ;\n    martech:measured_component data:component_checkouts .\n\ndata:measurement_order a martech:Measurement ;\n    martech:measured_entity data:stage_order ;\n    martech:measured_component data:component_orders .\n";
const LOGIN_TTL = "# ==========================================================================\n# Customer login journey — instance data\n# Conforms to: martech-ontology.ttl (load alongside ontology + other journeys)\n# ==========================================================================\n\n@prefix martech: <https://example.org/martech/ontology/> .\n@prefix data:    <https://example.org/martech/data/login/> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n\n# --------------------------------------------------------------------------\n# Requirement\n# --------------------------------------------------------------------------\n\ndata:req_login_frequency a martech:Requirement ;\n    rdfs:label \"Understand monthly login frequency\" ;\n    rdfs:comment \"We want to know how many logins we have monthly (MAU), and how that compares to overall sessions.\" ;\n    martech:status \"active\" ;\n    martech:addressed_by data:kpi_login_rate .\n\n# --------------------------------------------------------------------------\n# KPI\n# --------------------------------------------------------------------------\n\ndata:kpi_login_rate a martech:KPI ;\n    rdfs:label \"Monthly login rate\" ;\n    martech:formula \"Monthly logins / Sessions\" ;\n    martech:owner \"Product Analytics\" ;\n    martech:target 0.35 ;\n    rdfs:comment \"Target: 35% of monthly sessions include a login (illustrative example, not a real commitment).\" .\n\n# --------------------------------------------------------------------------\n# Journey\n# --------------------------------------------------------------------------\n\ndata:journey_login a martech:Journey ;\n    rdfs:label \"Customer login journey\" ;\n    martech:owner \"Product Analytics\" ;\n    martech:has_stage data:stage_login, data:stage_login_success .\n\n# --------------------------------------------------------------------------\n# Stages — share one component, distinguished by filter_value\n# (same pattern used whenever multiple stages share one dimension,\n# distinguished only by its value)\n# --------------------------------------------------------------------------\n\ndata:stage_login a martech:Stage ;\n    rdfs:label \"Login\" ;\n    martech:order 1 .\n\ndata:stage_login_success a martech:Stage ;\n    rdfs:label \"Login success\" ;\n    martech:order 2 ;\n    martech:rolls_up_to data:kpi_login_rate .\n\n# --------------------------------------------------------------------------\n# Component\n# NOTE: refs strips the redundant \"xdm.\" prefix from the given path,\n# since the namespace already encodes the /xdm/ segment. Flagging this\n# normalization — reverse it if that's wrong.\n# --------------------------------------------------------------------------\n\ndata:component_page_name a martech:Component ;\n    rdfs:label \"Page name\" ;\n    martech:component_type \"dimension\" ;\n    martech:definition \"The page name/path captured on each page view; used here to identify funnel steps by value.\" ;\n    martech:caveats \"A shared, general-purpose dimension — filtering by value (e.g. /customer/login) is required to isolate a specific journey step. The raw component alone doesn't identify a stage.\" ;\n    martech:context \"A general-purpose dimension, likely reused by other journeys in a real implementation — filtering by value is what distinguishes each specific use, not the component itself.\" ;\n    martech:owner \"Digital Analytics\" ;\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/web.webPageDetails.name> .\n\n# --------------------------------------------------------------------------\n# Data layer variable\n# --------------------------------------------------------------------------\n\ndata:dlv_page_info_name a martech:DataLayerVariable ;\n    rdfs:label \"digitalData.page.pageInfo.name\" ;\n    martech:source_system \"Web data layer (digitalData)\" ;\n    martech:maps_to data:component_page_name .\n\n# --------------------------------------------------------------------------\n# Measurements — same component, different filter_value per stage\n# --------------------------------------------------------------------------\n\ndata:measurement_login a martech:Measurement ;\n    martech:measured_entity data:stage_login ;\n    martech:measured_component data:component_page_name ;\n    martech:filter_value \"/customer/login\" .\n\ndata:measurement_login_success a martech:Measurement ;\n    martech:measured_entity data:stage_login_success ;\n    martech:measured_component data:component_page_name ;\n    martech:filter_value \"/customer/login/success\" .\n";
